  "privWho1": "Cook được vận hành bởi [tên pháp lý và địa chỉ bưu chính của đơn vị vận hành]. Liên hệ [địa chỉ email về quyền riêng tư] nếu có câu hỏi hoặc yêu cầu về quyền riêng tư. Các thông tin này phải được hoàn thiện trước khi mở đăng ký.",
  "privWhat1": "Khi bạn tạo tài khoản, chúng tôi dùng email, mã định danh tài khoản, hồ sơ xác thực bằng mật khẩu và trạng thái xác minh để cung cấp và bảo vệ tài khoản của bạn. Nhà cung cấp xác thực xử lý mật khẩu dưới dạng mã băm an toàn; Cook không lưu mật khẩu có thể đọc được. Chúng tôi lưu bố trí bếp, ngôn ngữ đã chọn, giao diện và đơn vị đo để khôi phục cài đặt của bạn trên mọi thiết bị. Cần có email và mật khẩu để tạo tài khoản; bạn vẫn có thể xem công thức mà không cần tài khoản.",
  "privWhat2": "Việc xử lý tài khoản và cài đặt là cần thiết để cung cấp dịch vụ tài khoản mà bạn yêu cầu (Điều 6(1)(b) GDPR). Một số hồ sơ hạn chế về bảo mật và chống lạm dụng có thể được xử lý dựa trên lợi ích hợp pháp (Điều 6(1)(f)), trong phạm vi cần thiết và sau khi cân nhắc. Email xác minh và đặt lại mật khẩu là tin nhắn dịch vụ, không phải tiếp thị. Tính năng tài khoản không thêm quảng cáo hay phân tích.",
  "privStorage1": "Cook dùng sessionStorage để mang bếp, tiến độ nấu và các lựa chọn của bạn giữa các trang trong cùng một thẻ. Khi bạn đăng nhập, nó cũng giữ phiên xác thực của bạn. Trình duyệt thường xóa dữ liệu này khi phiên của thẻ kết thúc, nhưng tính năng khôi phục phiên của trình duyệt có thể giữ lại. Đăng xuất sẽ xóa dữ liệu thẻ của Cook. Việc đóng thông báo lưu trữ chỉ được ghi nhớ trong thẻ đó. Các tập lệnh của chính Cook không đặt cookie. Nhà cung cấp lưu trữ hoặc dịch vụ của bạn có thể có hoạt động xử lý bảo mật riêng, cần được ghi lại trước khi ra mắt.",
  "privStorage2": "Nút OK và nút đóng trên thông báo lưu trữ chỉ đóng thông báo. Chúng không cho phép phân tích, quảng cáo hay theo dõi tùy chọn nào khác. Mọi hình thức lưu trữ không thiết yếu trong tương lai sẽ cần một lựa chọn riêng trước khi bắt đầu, với việc từ chối và rút lại dễ dàng như nhau.",
  "privOther1": "Tính năng giọng nói hiện tại của danh sách công thức hỏi country.is về quốc gia gần đúng dựa trên địa chỉ IP của bạn để chọn ngôn ngữ nhận dạng giọng nói. Nếu bạn dùng nhận dạng qua micro, trình duyệt có thể gửi âm thanh đến nhà cung cấp dịch vụ nhận dạng giọng nói của nó. Bạn cũng có thể gõ nguyên liệu. Các nhà cung cấp này, chính sách của họ và cơ sở pháp lý của các tính năng này phải được xem xét trước khi ra mắt công khai.",
  "privProviders1": "Nhà cung cấp tài khoản dự kiến: Supabase (PostgreSQL và xác thực được quản lý), với vùng cơ sở dữ liệu đã chọn tại EU. Nhà cung cấp email: [nhà cung cấp]. Lưu trữ trang web: [nhà cung cấp]. Đơn vị vận hành phải xác nhận các nhà cung cấp thực tế, thỏa thuận xử lý, bên xử lý phụ, vị trí lưu nhật ký và mọi hoạt động chuyển dữ liệu ra ngoài EEA. Một vùng cơ sở dữ liệu tại EU tự nó không loại trừ việc chuyển dữ liệu quốc tế. Khi phù hợp, hãy nêu quyết định về mức độ bảo vệ đầy đủ hoặc biện pháp bảo vệ theo hợp đồng được áp dụng và cách nhận bản sao.",
  "privRetention1": "Cài đặt tài khoản được giữ khi tài khoản của bạn còn hoạt động. Bạn có thể yêu cầu xóa qua đầu mối liên hệ về quyền riêng tư ở trên. Trước khi ra mắt, đơn vị vận hành phải quy định quy trình phản hồi yêu cầu xóa, thời hạn hết hiệu lực của tài khoản chưa xác minh và thời gian lưu giữ nhật ký bảo mật và bản sao lưu. Dữ liệu đã xóa có thể vẫn còn trong các bản sao lưu bị hạn chế truy cập cho đến khi hết thời gian lưu giữ đã ghi nhận.",
  "privRights1": "Tùy theo điều kiện áp dụng, bạn có thể yêu cầu truy cập, chỉnh sửa, xóa, hạn chế hoặc chuyển dữ liệu, hoặc phản đối việc xử lý dựa trên lợi ích hợp pháp. Hãy liên hệ đơn vị vận hành ở trên; yêu cầu thường được trả lời trong vòng một tháng, mọi gia hạn hợp pháp đều được giải thích. Bạn có thể khiếu nại với cơ quan giám sát, bao gồm NAIH của Hungary tại naih.hu. Cook không dùng cài đặt tài khoản cho các quyết định tự động có tác động pháp lý hoặc tác động đáng kể tương tự.",
