  "Cut into 1 cm cubes.": "Cắt thành miếng 1 cm.",
  "Pepper and cheese": "Tiêu và phô mai",
  "Grind the peppercorns to a powder and sieve it. Finely grate the pecorino.": "Giã tiêu thành bột và rây. Bào mịn Pecorino.",
  "Pepper ground, cheese grated": "Đã xay tiêu, đã bào phô mai",
  "Beat the eggs with most of the pecorino until smooth. Keep the rest for serving.": "Đánh trứng với phần lớn Pecorino cho đến khi mịn. Giữ phần còn lại để rắc khi dọn.",
