  "Put the diced guanciale into the COLD pan, then turn the burner to LOW. Lean guanciale? Add 1 tsp neutral oil first. Let the fat melt out slowly for about 9 minutes, stirring now and then.": "Cho guanciale đã cắt vào chảo NGUỘI, rồi vặn bếp lửa NHỎ. Guanciale ít mỡ? Cho 1 muỗng cà phê dầu ăn trước. Thắng mỡ từ từ khoảng 9 phút, thỉnh thoảng đảo.",
  "Cook the spaghetti": "Luộc spaghetti",
