  "Put the diced guanciale into the COLD pan, then turn the burner to LOW. Lean guanciale? Add 1 tsp neutral oil first. Add the lightly crushed whole garlic clove.": "Cho guanciale đã cắt vào chảo NGUỘI, rồi vặn bếp lửa NHỎ. Guanciale ít mỡ? Cho 1 muỗng cà phê dầu ăn trước. Cho một tép tỏi nguyên đập dập nhẹ vào.",
  "Pepper in, garlic out": "Đã cho tiêu, đã bỏ tỏi",
