  "Put the diced guanciale into the COLD pan, then turn the burner to LOW. Lean guanciale? Add 1 tsp neutral oil first. Add the lightly crushed whole garlic clove. Let the fat melt out slowly for about 9 minutes, stirring now and then.": "Cho guanciale đã cắt vào chảo NGUỘI, rồi vặn bếp lửa NHỎ. Guanciale ít mỡ? Cho 1 muỗng cà phê dầu ăn trước. Cho một tép tỏi nguyên đập dập nhẹ vào. Thắng mỡ từ từ khoảng 9 phút, thỉnh thoảng đảo.",
  "Pepper in, garlic out, heat off": "Đã cho tiêu, đã bỏ tỏi, đã tắt bếp",
  "Stir in about half of the ground pepper. Take the garlic clove out if it is golden brown. Then turn off the burner and take the pan off the heat.": "Khuấy khoảng một nửa lượng tiêu đã xay vào. Vớt tép tỏi ra nếu đã vàng nâu. Rồi tắt bếp và nhấc chảo ra khỏi lửa.",
