  "Beat the yolks and whole eggs with most of the pecorino until smooth. Keep the rest for serving.": "Đánh lòng đỏ và trứng nguyên quả với phần lớn Pecorino cho đến khi mịn. Giữ phần còn lại để rắc khi dọn.",
