  "Toast each tortilla in a dry hot pan, 15 to 25 s per side.": "Nướng từng chiếc tortilla trên chảo khô nóng, mỗi mặt 15 đến 25 giây.",
  "Lightly charred spots": "Có vài đốm cháy nhẹ",
  "Ladle into bowls. Top with grated cheddar, a spoon of sour cream and a few cilantro leaves. Tortillas (or rice) on the side, lime wedge optional.": "Múc ra tô. Rắc Cheddar bào, một thìa kem chua và vài lá ngò lên trên. Ăn kèm tortilla (hoặc cơm) và một lát chanh nếu thích.",
  "Dice the onion … Chop the tomatoes": "Thái hành tây … Thái cà chua",
  "Onion and pepper in … Taste and adjust": "Cho hành tây và ớt chuông … Nếm và nêm lại",
  "Cook the rice": "Nấu cơm",
  "Wash the rice until the water runs clear. Cook it in 1.5× its volume of lightly salted water; when the water level meets the rice, cover on the lowest heat for 10 to 12 min, then rest covered 10 to 15 min.": "Vo gạo đến khi nước trong. Nấu trong lượng nước muối nhạt bằng 1.5× lượng gạo; khi nước cạn ngang mặt gạo, đậy nắp ở lửa nhỏ nhất 10 đến 12 phút, rồi để nguyên nắp ủ 10 đến 15 phút.",
  "Fluffy, water absorbed": "Tơi, đã hút hết nước",
  "Grate the cheddar · Serve": "Bào Cheddar · Dọn ra",
  "Milk on the stove": "Đặt sữa lên bếp",
  "Pour the milk into a big pot and put it on the stove.": "Đổ sữa vào nồi lớn và đặt lên bếp.",
  "Pot on the burner": "Nồi đã ở trên bếp",
  "Crack the cardamom": "Tách bạch đậu khấu",
  "Break the pods, throw away the husks and crush the seeds in the mortar (or use ground cardamom).": "Tách vỏ, bỏ vỏ và giã hạt trong cối (hoặc dùng bạch đậu khấu xay sẵn).",
  "Seeds crushed": "Đã giã hạt",
  "Add the cinnamon and the crushed cardamom seeds to the milk.": "Cho quế và hạt bạch đậu khấu đã giã vào sữa.",
  "Spices in the milk": "Gia vị đã vào sữa",
  "Portion semolina and sugar": "Đong bột semolina và đường",
  "Measure the semolina and the sugar (or erythritol). Per 1 dl milk: 1 tbsp semolina, ½ tbsp sugar (or ⅔ tbsp erythritol).": "Đong bột semolina và đường (hoặc erythritol). Cho mỗi 1 dl sữa: 1 muỗng canh semolina, ½ muỗng canh đường (hoặc ⅔ muỗng canh erythritol).",
  "Both measured": "Đã đong cả hai",
  "Heat until steaming": "Đun đến khi bốc hơi",
  "Let the milk heat up until it steams.": "Đun sữa cho đến khi bốc hơi.",
  "Steam rises from the milk": "Sữa đang bốc hơi",
  "Stir constantly": "Khuấy liên tục",
  "Once it steams, stir constantly until it starts to rise.": "Khi đã bốc hơi, khuấy liên tục cho đến khi sữa trào lên.",
  "Milk starts to rise": "Sữa bắt đầu trào",
  "Semolina and sugar in": "Cho semolina và đường",
  "Pour in the semolina slowly, then the sugar, stirring all the time. Turn the heat to low.": "Rắc từ từ semolina vào, rồi đến đường, khuấy liên tục. Hạ lửa.",
  "No lumps": "Không vón cục",
  "Cook on low": "Ninh nhỏ lửa",
  "Keep stirring on low heat.": "Tiếp tục khuấy trên lửa nhỏ.",
  "Thick and smooth": "Đặc và mịn",
  "Heat off, rosewater": "Tắt bếp, nước hoa hồng",
  "Turn off the heat. Add a little rosewater near the end and keep stirring.": "Tắt bếp. Cuối cùng cho chút nước hoa hồng và tiếp tục khuấy.",
  "Rosewater stirred in": "Đã cho nước hoa hồng",
  "Plate while hot": "Dọn khi còn nóng",
  "While it is still hot and runny, pour it onto flat plates. Once it cools in the pot it sets and won't spread.": "Khi còn nóng và lỏng, đổ ra đĩa phẳng. Nếu để nguội trong nồi, nó sẽ đông lại và không dàn ra được.",
  "Spread on the plates": "Đã dàn ra đĩa",
  "Dust and serve": "Rắc và dọn",
  "Just before serving, sprinkle cocoa powder (and cinnamon) on top.": "Rắc bột ca cao (và quế) ngay trước khi dọn.",
  "Dusted": "Đã rắc",
  "Milk on the stove … Heat off, rosewater": "Đặt sữa lên bếp … Tắt bếp, nước hoa hồng",
  "Crack the cardamom · Portion semolina and sugar": "Tách bạch đậu khấu · Đong bột semolina và đường",
  "Plate while hot · Dust and serve": "Dọn khi còn nóng · Rắc và dọn",
  "Dice the chicken": "Cắt gà",
  "Cut the chicken breast into small 2 to 3 cm chunks.": "Cắt ức gà thành miếng nhỏ 2 đến 3 cm.",
  "Even chunks": "Miếng đều nhau",
  "Grate the garlic": "Bào tỏi",
  "Finely grate the garlic (for the marinade and the sauce).": "Bào nhuyễn tỏi (cho nước ướp và sốt).",
  "Mix the marinade": "Pha nước ướp",
  "In a container, add the chicken with the oil, gochujang, light soy sauce, salt, MSG, white pepper, sugar or honey, garlic and sesame oil. Mix well and cover.": "Cho gà vào hộp cùng dầu, gochujang, xì dầu nhạt, muối, bột ngọt, tiêu trắng, đường hoặc mật ong, tỏi và dầu mè. Trộn đều và đậy nắp.",
  "Chicken evenly coated": "Gà được phủ đều",
  "Marinate in the fridge": "Ướp trong tủ lạnh",
  "Leave it covered in the fridge.": "Đậy nắp và để trong tủ lạnh.",
  "At least 30 min passed": "Đã qua ít nhất 30 phút",
  "Measure rice and water": "Đong gạo và nước",
  "Measure the rice in cups. In a bowl, mix 1.5× its volume of water with the salt.": "Đong gạo bằng cốc. Trong một tô, pha lượng nước bằng 1.5× lượng gạo với muối.",
  "Measured": "Đã đong",
  "Wash the rice": "Vo gạo",
  "Wash the rice in lukewarm water in a sieve, stirring slowly, until the water runs clear. Let it drain a little.": "Vo gạo trong rổ bằng nước ấm, khuấy nhẹ, đến khi nước trong. Để ráo bớt.",
  "Water runs clear": "Nước đã trong",
  "Toast the rice": "Rang gạo",
  "Heat the oil in a pan and toast the rice, stirring slowly, until it smells fragrant. Don't really fry it.": "Đun nóng dầu trong chảo và rang gạo, khuấy nhẹ, đến khi thơm. Không chiên thật sự.",
  "Water in": "Cho nước",
  "Add the salted water and stir once, very slowly.": "Đổ nước muối vào và khuấy rất nhẹ một lần.",
  "Boil down": "Đun cạn nước",
  "Let it boil until the water level roughly matches the rice level.": "Đun sôi đến khi mực nước xuống gần ngang mặt gạo.",
  "Water level at the rice": "Nước ngang mặt gạo",
  "Cover, lowest heat": "Đậy nắp, lửa nhỏ nhất",
  "Set the lowest heat and cover. Don't stir or lift the lid.": "Vặn lửa nhỏ nhất và đậy nắp. Không khuấy, không mở nắp.",
  "Time is up": "Đã hết giờ",
  "Rest, covered": "Ủ có nắp",
  "Take it off the heat, keep the lid on.": "Nhấc khỏi bếp, giữ nguyên nắp.",
  "Rested": "Đã ủ xong",
  "Julienne the vegetables": "Thái sợi rau củ",
  "Cut the carrot, the cucumber (easy option) and the white part of the green onions into matchsticks. Chop the green parts for topping.": "Thái cà rốt, dưa chuột (lựa chọn dễ) và phần trắng của hành lá thành sợi như que diêm. Thái phần xanh để rắc lên trên.",
  "Matchstick-sized": "Sợi cỡ que diêm",
  "Prepare the bok choy": "Sơ chế cải thìa",
  "Tear the bok choy apart by leaves and wash it thoroughly.": "Tách lá cải thìa và rửa sạch.",
  "Clean leaves": "Lá sạch",
  "Mix the sauce": "Pha sốt",
  "Mix the gochujang, sesame oil, sugar or honey, rice vinegar, water, sesame seeds and grated garlic.": "Trộn gochujang, dầu mè, đường hoặc mật ong, giấm gạo, nước, mè và tỏi bào.",
  "Smooth sauce": "Sốt mịn",
  "Chicken into the pan": "Gà vào chảo",
  "Heat a large pan on medium-high with a little oil. Add the marinated chicken.": "Đun nóng chảo lớn với chút dầu ở lửa vừa-lớn. Cho gà đã ướp vào.",
