  "Clean the pan (or use another). While cold, add a few tbsp of water and a few tsp of oil, then heat it.": "Lau chảo (hoặc dùng chảo khác). Khi còn nguội, cho vài muỗng canh nước và vài muỗng cà phê dầu, rồi đun nóng.",
  "Hot and steaming": "Nóng và bốc hơi",
  "Steam-fry the bok choy": "Xào hấp cải thìa",
  "Add the bok choy with a little salt, stirring. Don't overcook it.": "Cho chút muối rồi cho cải thìa vào, vừa cho vừa đảo. Đừng nấu quá kỹ.",
  "Just wilted, still green": "Vừa héo, vẫn còn xanh",
  "Fry the eggs": "Chiên trứng",
  "Fry the eggs sunny side up in a small pan with a little oil, one at a time. Keep the yolk a little runny, salt a tiny bit, add a splash of sesame oil near the end.": "Chiên từng quả trứng ốp la trong chảo nhỏ với chút dầu. Giữ lòng đỏ hơi lòng đào, rắc chút muối, cuối cùng nhỏ vài giọt dầu mè.",
  "White set, yolk runny": "Lòng trắng chín, lòng đỏ lòng đào",
  "Plate it": "Bày đĩa",
