  "Toast the rice … Rest, covered": "Rang gạo … Ủ có nắp",
  "Mix the sauce · Plate it": "Pha sốt · Bày đĩa",
  "Chicken into the pan … Steam-fry the bok choy": "Gà vào chảo … Xào hấp cải thìa",
