  "Shred the cucumber, add a pinch of salt.": "Bào dưa chuột, cho một nhúm muối.",
  "Shredded, salted": "Đã bào, đã ướp muối",
  "Let the cucumber rest": "Để dưa chuột nghỉ",
  "Let it rest.": "Để yên.",
  "Squeeze the cucumber": "Vắt dưa chuột",
  "Squeeze the water out.": "Vắt bỏ nước.",
