  "Sauté the julienned carrot for about 1 minute.": "Xào cà rốt thái sợi khoảng 1 phút.",
  "Slightly soft": "Hơi mềm",
  "Shred and salt the cucumber · Let the cucumber rest": "Bào dưa chuột và ướp muối · Để dưa chuột nghỉ",
  "Squeeze the cucumber · Prepare the bok choy": "Vắt dưa chuột · Sơ chế cải thìa",
  "Chicken into the pan … Sauté the carrot": "Gà vào chảo … Xào cà rốt",
  "Cut the chicken breast into chunks (about 3 cm).": "Cắt ức gà thành miếng (khoảng 3 cm).",
  "Add the chicken to a container with a little oil, salt, mustard, honey, tarragon, the white wine (or stock + lemon juice), black pepper and a very small amount of MSG. Mix well and cover.": "Cho gà vào hộp với chút dầu, muối, mù tạt, mật ong, ngải giấm, rượu vang trắng (hoặc nước dùng + nước cốt chanh), tiêu và một chút xíu bột ngọt. Trộn đều và đậy nắp.",
