  "Thin slices": "Lát mỏng",
  "Make the marinade": "Pha nước ướp",
  "Mix the lemon juice, mustard, garlic, crumbled stock cube, pepper, salt and half the oil. Add the chicken and the onions and mix well.": "Trộn nước cốt chanh, mù tạt, tỏi, viên súp bóp vụn, tiêu, muối và một nửa dầu. Cho gà và hành vào trộn đều.",
  "Everything coated": "Đã phủ đều",
