  "Lift the chicken out of the marinade (keep the onions and the marinade) and brown it in the rest of the oil. Take it out.": "Gắp gà ra khỏi nước ướp (giữ lại hành và nước ướp) và áp chảo trong phần dầu còn lại. Gắp ra.",
  "Browned on both sides": "Vàng cả hai mặt",
  "Cook the onions": "Xào hành",
  "Fry the onions from the marinade in the same pan until soft and golden.": "Xào hành đã ướp trong cùng chảo cho đến khi mềm và vàng.",
  "Add the rest of the marinade, the water and the bay leaf (and the chili), put the chicken back, cover and simmer until the chicken is tender. Add the olives for the last 5 minutes.": "Thêm phần nước ướp còn lại, nước và lá nguyệt quế (và ớt), cho gà trở lại, đậy nắp và om cho đến khi gà mềm. Cho ô liu vào 5 phút cuối.",
  "Chicken tender, onions jammy": "Gà mềm, hành như mứt",
