  "Rough paste": "Hỗn hợp thô",
  "Mix the oyster sauce, both soy sauces, fish sauce, sugar and water.": "Trộn dầu hào, cả hai loại nước tương, nước mắm, đường và nước.",
  "Heat the oil in the wok until very hot and fry the eggs one at a time, spooning hot oil over them, until the edges are crispy and the yolk is still runny. Keep them on a plate.": "Đun dầu thật nóng trong chảo wok và chiên từng quả trứng, chan dầu nóng lên trên, cho đến khi mép giòn mà lòng đỏ còn lòng đào. Để riêng ra đĩa.",
  "Crispy edges, runny yolk": "Mép giòn, lòng đỏ lòng đào",
  "Fry the garlic and chilies": "Phi tỏi và ớt",
  "Heat the oil in the wok and fry the garlic and chili paste for a few seconds until fragrant.": "Đun nóng dầu trong chảo wok và phi hỗn hợp tỏi ớt vài giây cho đến khi thơm.",
